 if(Array.isArray(u.review))out.review=u.review.filter(x=>x&&WKEYS.includes(x.topic)&&typeof x.kind==='string'&&Number.isInteger(x.step)).map(x=>({topic:x.topic,kind:x.kind,step:x.step,box:Math.max(0,Math.min(3,x.box|0)),due:Number(x.due)||0})).slice(-30);
 const S=u.settings&&typeof u.settings==='object'?u.settings:{};out.settings={pace:['rustig','normaal','uitdaging'].includes(S.pace)?S.pace:'normaal',read:S.read===true,timer:S.timer!==false};
 for(const key of ['errs','best','goal'])if(u[key]&&typeof u[key]==='object'&&!Array.isArray(u[key]))out[key]=u[key];
