function syncJoinHtml(){return `<details class="sync-more"><summary>Speelt deze speler al op een ander apparaat?</summary><p class="small-note">Kijk daar bij de speler (tandwieltje) onder Op andere apparaten, en vul die code hier in.</p><label class="field"><span>Code</span><input id="sync-join" maxlength="12" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="KBTQ-7M4X"></label><button class="button purple" data-action="sync-add">${icon('check')} Voortgang ophalen</button></details>`;}
