function speak(text,force=false){if(!supportsVoice){if(!voiceWarning){toast('Voorlezen is niet beschikbaar in deze browser. Probeer Safari of Chrome.');voiceWarning=true;}return;}if(!voice&&!force)return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='nl-NL';const v=availableVoices.find(v=>v.lang.toLowerCase()==='nl-nl')||availableVoices.find(v=>v.lang.toLowerCase().startsWith('nl'));if(v)u.voice=v;u.rate=.88;u.pitch=1.08;u.onerror=e=>{if(e.error!=='canceled'&&e.error!=='interrupted')toast('De stem werkt hier niet. Controleer de Nederlandse spraakinstellingen van je apparaat.');};speechSynthesis.speak(u);}
function sound(type){if(!voice)return;try{audioContext ||= new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();const tones=type==='win'?[523,659,784,1047]:type==='tap'?[660]:[523,659];tones.forEach((freq,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain(),at=audioContext.currentTime+i*.10;o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.0001,at);g.gain.exponentialRampToValueAtTime(.07,at+.02);g.gain.exponentialRampToValueAtTime(.0001,at+.24);o.connect(g);g.connect(audioContext.destination);o.start(at);o.stop(at+.25);});}catch{}}
