function kgRank(u){const k=u.kanga||{level:kgLevelFor(u.groep),skill:{}};return puzzleLevel(k,k.level);}
function kgBadge(r,cls=''){return `<span class="kg-rank ${cls}" aria-label="Kangoeroe ${r.levelName}, niveau ${r.n} van 5: ${r.name}"><span class="kg-rank-ico" aria-hidden="true">🦘</span><span class="kg-rank-txt"><b>Niveau ${r.n}</b><small>${r.name} · ${r.levelName}</small></span><span class="kg-rank-dots" aria-hidden="true">${[1,2,3,4,5].map(i=>`<i class="${i<=r.n?'on':''}"></i>`).join('')}</span></span>`;}
function moreGames(){const r=kgRank(U());return `<section class="more-games"><div class="section-title"><h2>Meer spellen</h2></div><div class="game-tiles">
<button class="game-tile sprint" data-action="nav" data-page="sprint"><span class="gt-ico">${icon('clock')}</span><strong>Rekensprint</strong><span>Hoeveel sommen in 1, 2 of 3 minuten?</span></button>
<button class="game-tile kanga" data-action="nav" data-page="kangoeroe"><span class="gt-ico" aria-hidden="true">🦘</span><strong>Kangoeroe</strong>${kgBadge(r,'small')}</button>
<button class="game-tile leger" data-action="nav" data-page="leger"><span class="gt-ico">${icon('shield')}</span><strong>Rekenleger</strong><span>${(()=>{const d=cleanLeger(U().leger);const t=Object.values(d.stars).reduce((a,b)=>a+b,0);return t?`${t} sterren · bouw je leger met sommen`:'Bouw een leger met sommen. Nieuw!';})()}</span></button>
<button class="game-tile ster" data-action="nav" data-page="ster"><span class="gt-ico">${icon('camera')}</span><strong>Rekenster</strong><span>${(()=>{const d=cleanSter(U().ster);return d.followers?`${d.followers.toLocaleString('nl-NL')} volgers · ${titleForSter(d.followers)}`:'Style je blogger: links of rechts? Nieuw!';})()}</span></button>
<button class="game-tile arena" data-action="nav" data-page="battle"><span class="gt-ico">${icon('sparkles')}</span><strong>Rekenarena</strong><span>Daag elkaar uit, samen of online.</span></button></div></section>`;}
function home(){const profile=p();return `<div class="page-heading"><div><div class="eyebrow">HÉ, ${escapeHTML(U().name).toUpperCase()}!</div><h1>Jouw avontuur wacht <span class="heading-star">✦</span></h1></div><div class="heading-actions"><button class="groep-chip" data-action="player-edit" data-id="${U().id}" aria-label="Groep ${U().groep}, wijzigen">Groep <b>${U().groep}</b> ${icon('settings')}</button><button class="listen-label" data-action="welcome">${icon('volume')} Luister</button></div></div><section class="adventure-banner"><img class="banner-image" src="/assets/avontuur.webp" width="1536" height="1024" alt="Lumi de draak en Fikkie de vos ontdekken een magisch ei op een zwevend eiland"><div class="banner-content"><h2>Kleine sommen.<br>Groot avontuur.</h2><p>Maak 6 opdrachten.<br>Wie komt er uit jouw ei?</p><button class="button yellow big" data-action="start" data-topic="mix">${icon('play')} Spelen maar!</button><span class="banner-note">Op jouw niveau · Met voorlezen</span></div></section><div class="home-grid"><section class="worlds"><div class="section-title"><h2>Kies jouw avontuur</h2><span>Alles mag. Jij kiest.</span></div><div class="world-grid">${Object.entries(TOPICS).map(([key,t])=>`<button class="world-card ${t.color}" data-action="start" data-topic="${key}" aria-label="Speel ${wname(key)}"><span class="world-icon">${icon(t.icon)}</span><span class="world-name">${wname(key)}</span><span class="world-level">${key==='add'?'Het telbos':key==='tables'?'De groepjesgrot':key==='fractions'?'Het stukkeneiland':key==='life'?'De wonderwinkel':'De denkberg'}</span><span class="world-go">${icon('play')}</span></button>`).join('')}<button class="world-card orange" data-action="table-picker"><span class="world-icon">${icon('grid')}</span><span class="world-name">Tafels 1 t/m 10</span><span class="world-level">Kies jouw tafel</span><span class="world-go">${icon('play')}</span></button></div><div class="gentle-note">${icon('bulb')} Te makkelijk? Je sommen groeien met je mee.</div></section><section class="egg-card"><span class="eyebrow">JOUW VOLGENDE VRIENDJE</span><div class="egg-display" aria-hidden="true">🥚<span class="egg-spark s1">✦</span><span class="egg-spark s2">✧</span></div><h3>${GROUPS[profile.eggGroup].name}</h3><p>${groupProgress(profile,profile.eggGroup)} van de 10 ontdekt</p><button class="text-button" data-action="egg-picker">Kies een ander ei ${icon('arrow')}</button><div class="egg-dots" role="img" aria-label="Zes sommen per avontuur">${Array.from({length:6},()=>'<span></span>').join('')}</div><span class="small-note">6 sommen · Alle tijd voor jou</span></section></div>${moreGames()}`;}
const PACE={rustig:.85,normaal:.75,uitdaging:.62};
const paceTarget=u=>PACE[u?.settings?.pace]||.75;
function newQ(){const u=U();let rv=null,twin=null;
 if(round.mode!=='check'&&!round.tableMode){if(round.twin){twin=round.twin;round.twin=null;}else if(round.index===2||round.index===4){const now=Date.now();rv=u.review.filter(x=>x.due<=now&&(round.focus==='mix'||x.topic===round.focus)&&!round.reviewed.includes(x.kind)).sort((a,b)=>a.due-b.due)[0]||null;if(rv)round.reviewed.push(rv.kind);}}
 const src=twin||rv,topic=src?.topic||round.order[round.index%round.order.length];let q;
 for(let i=0;i<12;i++){if(round.tableMode)q=PZ.tablePuzzle(round.table,round.factors[round.index%10],round.index);else if(src&&i<8&&PZ.kindsFor(src.topic,src.step).includes(src.kind))q=PZ.makeKind(src.kind,src.topic,src.step);else if(!src&&u.settings.pace==='uitdaging'&&round.mode!=='check'&&round.focus==='mix'&&Math.random()<.2&&LM.mastery(u.skill.logic)>=3)q=PZ.makeKind('open','logic',LM.pickStep(u.skill.logic,Math.random,'practice',.6,paceTarget(u)));else q=PZ.makePuzzle(topic,src?src.step:LM.pickStep(u.skill[topic],Math.random,round.mode,0,paceTarget(u)),Math.random,round.kinds);if(!round.seen.has(q.key))break;}
 round.seen.add(q.key);round.kinds=[...round.kinds.slice(-3),q.kind];round.q=q;round.st=PZ.newState(q);Object.assign(round,{mistakes:0,done:false,hint:false,hintLevel:0,stepText:'',diag:null,feedback:'',helped:false,revealed:false,firstFrac:0,preHint:0,review:!!rv,isTwin:!!twin,qStart:Date.now()});}
/* ---------- weekdoel: het kind kiest zelf een doel (zelfsturing) ---------- */
function weekKey(d=new Date()){const t=new Date(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate()));const day=t.getUTCDay()||7;t.setUTCDate(t.getUTCDate()+4-day);const y=new Date(Date.UTC(t.getUTCFullYear(),0,1));return t.getUTCFullYear()+'-W'+String(Math.ceil(((t-y)/864e5+1)/7)).padStart(2,'0');}
function weekDays(u){const now=new Date(),day=(now.getDay()+6)%7,mon=new Date(now.getFullYear(),now.getMonth(),now.getDate()-day);return Object.entries(u.days).filter(([d,v])=>new Date(d)>=mon&&v.n>0).length;}
function goalOptions(u){const out=[{type:'days',target:4,label:'Speel op 4 dagen deze week'}];
 const weakT=Array.from({length:9},(_,i)=>i+2).find(t=>LM.factState(u.facts['t'+t])!=='vlot'&&(u.groep>=4||t<=5||t===10));
 if(weakT&&u.groep>=4)out.push({type:'table',table:weakT,target:1,label:`Maak de tafel van ${weakT} vlot (in de Tafelclub)`});else if(u.groep<=4)out.push({type:'world',world:'add',target:12,label:`12 opdrachten in één keer goed bij ${wname('add',u)}`});
 const w=WKEYS.map(k=>[k,LM.mastery(u.skill[k])]).sort((a,b)=>a[1]-b[1])[0][0];out.push({type:'world',world:w,target:15,label:`15 opdrachten in één keer goed bij ${wname(w,u)}`});return out;}
function goalProgress(u){const g=u.goal;if(!g)return null;if(g.type==='days')return Math.min(g.target,weekDays(u));if(g.type==='table')return LM.factState(u.facts['t'+g.table])==='vlot'?1:0;return Math.min(g.target,g.n||0);}
function pickGoal(i){const u=U(),o=goalOptions(u)[i];if(!o)return;u.goal={...o,week:weekKey(),n:0,done:false};save();render();speak(`Jouw doel: ${o.label}. Zet hem op!`);}
function goalTick(u,q,ok){const g=u.goal;if(!g||g.week!==weekKey()||g.done)return;if(g.type==='world'&&ok&&q.topic===g.world)g.n=(g.n||0)+1;if(goalProgress(u)>=g.target){g.done=true;u.profile.stars+=5;setTimeout(()=>{toast(`Weekdoel gehaald: ${g.label}! Je krijgt 5 extra sterren.`);speak('Weekdoel gehaald! Super gedaan.');},400);}}
function goalCard(u){const g=u.goal&&u.goal.week===weekKey()?u.goal:null;if(!g)return `<section class="goal-card"><h2>${icon('flag')} Kies je doel voor deze week</h2><div class="goal-options">${goalOptions(u).map((o,i)=>`<button class="goal-option" data-action="goal-pick" data-i="${i}">${o.label}</button>`).join('')}</div></section>`;
 const n=goalProgress(u),pct=Math.round(100*n/g.target);return `<section class="goal-card ${g.done?'done':''}"><h2>${icon(g.done?'check':'flag')} Mijn weekdoel</h2><p>${g.label}</p><div class="goal-bar"><i style="width:${pct}%"></i></div><small>${g.done?'Gehaald! Volgende week kies je een nieuw doel.':g.type==='table'?'Oefen in de Tafelclub en de Rekensprint.':`${n} van de ${g.target}`}</small></section>`;}
function hintText(){const q=round.q;return round.hintLevel>=3?round.stepText:round.hintLevel===2?q.hint:CO.question(q);}
function hintBox(){const q=round.q,L=round.hintLevel;if(!L&&!round.diag)return '';const title=['','Denk even na','Zo kun je het aanpakken','Ik doe de eerste stap'][L]||'Kijk eens';return `<div class="hint-box lvl${L}">${icon('bulb')}<div>${round.diag?`<p class="diag"><b>${round.diag.text}</b></p>`:''}${L?`<strong>${title}</strong><p>${hintText()}</p>`:''}${L>=2?PZ.hintVisual(q):''}${L>=3&&round.hintLevel>=3&&round.stepText!==q.hint?'':''}</div></div>`;}
function applyFirstStep(){const q=round.q,st=round.st,fs=CO.firstStep(q,st);if(fs.cell){st.vals[fs.cell]=fs.value;st.marks[fs.cell]='shown';st.active=q.cells.find(c=>c.id!==fs.cell&&st.marks[c.id]!=='shown'&&st.marks[c.id]!=='ok')?.id||st.active;}round.stepText=fs.text;}
function workedHtml(q){const s=CO.steps(q);return s.length>1?`<ol class="worked">${s.map(x=>`<li>${x}</li>`).join('')}</ol>`:`<span>${s[0]||q.explanation}</span>`;}
function noteErr(code){const u=U();if(!u||!code)return;u.errs[code]=(u.errs[code]||0)+1;}
function queueTwin(q){if(round.mode==='check'||round.tableMode)return;if(round.isTwin&&round.twinChain>=1)return;round.twinChain=round.isTwin?(round.twinChain||0)+1:0;round.twin={kind:q.kind,topic:q.topic,step:q.level};if(round.index===round.len-1&&(round.extra||0)<2){round.len++;round.extra=(round.extra||0)+1;}}
function start(topic,tableMode=false,table=null,mode='practice'){if(!U())return;if(!TOPICS[topic]&&topic!=='mix')return;const check=mode==='check';round={mode,len:check?10:6,focus:topic,order:check?['add','tables','fractions','life','logic','add','tables','fractions','life','logic']:topic==='mix'?mixOrder(U().groep):[topic],index:0,correct:0,seen:new Set(),kinds:[],reviewed:[],twin:null,extra:0,q:null,tableMode,table,factors:Array.from({length:10},(_,i)=>i+1).map(n=>({n,r:Math.random()})).sort((a,b)=>a.r-b.r).map(x=>x.n)};if(check)round.before=Object.fromEntries(WKEYS.map(k=>[k,LM.mastery(U().skill[k])]));page='play';newQ();render();window.scrollTo(0,0);if(supportsVoice)speechSynthesis.cancel();speak((check?'Niveaucheck. Tien opdrachten uit alle werelden. Doe je best, en neem je tijd. ':'')+round.q.spoken);}
function visual(v){if(!v)return '';if(v.type==='clock'){const nums=Array.from({length:12},(_,i)=>{const n=i+1,ang=n*Math.PI/6;return `<text x="${100+Math.sin(ang)*72}" y="${106-Math.cos(ang)*72}" text-anchor="middle">${n}</text>`;}).join('');return `<svg class="math-clock" viewBox="0 0 200 200" role="img" aria-label="Klok met een korte uurwijzer en een lange minuutwijzer"><circle cx="100" cy="100" r="95"/><g class="clock-numbers">${nums}</g><line class="hour-hand" x1="100" y1="100" x2="100" y2="52" transform="rotate(${v.hour*30+v.minute*.5} 100 100)"/><line class="minute-hand" x1="100" y1="100" x2="100" y2="32" transform="rotate(${v.minute*6} 100 100)"/><circle class="clock-pin" cx="100" cy="100" r="5"/></svg>`;}
if(v.type==='fraction')return `<div class="fraction-bar" role="img" aria-label="${v.b} gelijke stukjes waarvan sommige paars zijn">${Array.from({length:v.b},(_,i)=>`<span class="${i<v.a?'filled':''}"></span>`).join('')}</div>`;
if(v.type==='dots'){const dots=n=>Array.from({length:n},()=>'<i></i>').join('');return `<div class="dot-visual" aria-label="Telhulp"><div>${dots(v.a)}</div><b>${v.minus?'−':'+'}</b><div class="${v.minus?'subtract':''}">${dots(v.b)}</div></div>`;}
if(v.type==='groups')return `<div class="group-visual" aria-label="${v.b} groepjes van ${v.a}">${Array.from({length:v.b},()=>`<div>${Array.from({length:v.a},()=>'<i></i>').join('')}</div>`).join('')}</div>`;
return '';}
function game(){const q=round.q,st=round.st,res=PZ.check(q,st),maxTries=3;return `<div class="game-top"><button class="quiet" data-action="exit">${icon('back')} <span>Avontuur</span></button><div class="round-progress" aria-label="Opdracht ${round.index+1} van ${round.len}">${Array.from({length:round.len},(_,i)=>`<span class="${i<round.index?'complete':i===round.index?'current':''}">${i<round.index?icon('check'):i+1}</span>`).join('')}<span class="tiny-egg" aria-hidden="true">🥚</span></div><span class="small-note">${round.mode==='check'?'Niveaucheck · ':''}${round.index+1} / ${round.len}</span></div><section class="question-card pz-card"><div class="question-meta"><span class="pill ${TOPICS[q.topic].color}">${icon(TOPICS[q.topic].icon)} ${round.tableMode?'Tafel van '+(q.table||round.table||''):wname(q.topic)}</span>${round.review?'<span class="pill review-pill">Herhaling</span>':''}${round.isTwin?'<span class="pill twin-pill">Tweelingsom</span>':''}<button class="listen-label" data-action="repeat">${icon('volume')} Luister</button></div><h1 class="pz-title">${q.title}</h1><div class="pz-body ${round.done||!q.cells.length?'nopad':''}">${PZ.view(q,st)}${round.done?'':PZ.padHtml(q,st)}</div>${!round.done?hintBox():''}<div class="question-footer" aria-live="polite">${round.done?`<div class="answer-feedback"><span class="success-mark ${round.revealed?'shown':''}">${icon(round.revealed?'bulb':'check')}</span><div><strong>${round.revealed?'Kijk, zo los je het op:':round.mistakes?'Goed doorgezet! Zo gaat het:':'Helemaal goed!'}</strong>${round.revealed||round.mistakes?workedHtml(q):`<span>${q.explanation}</span>`}${round.twin?`<em class="twin-note">${icon('sparkles')} Nu een tweelingsom: dezelfde soort, nieuwe getallen. Probeer het zelf!</em>`:''}</div></div><button class="button purple" data-action="next">${round.index===round.len-1?'Naar mijn ei':'Volgende'} ${icon('arrow')}</button>`:`<span class="feedback-text">${round.feedback||(q.cells.length?'Tik op een vakje en vul in. Klaar? Tik op Kijk na.':'Klaar? Tik op Kijk na.')}${round.mistakes?` <em class="tries">Nog ${maxTries-round.mistakes} ${maxTries-round.mistakes===1?'kans':'kansen'}</em>`:''}</span><div class="pz-actions">${round.hintLevel<3?`<button class="text-button" data-action="hint">${icon('bulb')} ${['Help me even','Meer hulp','Doe de eerste stap voor'][round.hintLevel]}</button>`:'<span></span>'}<button class="button purple" data-action="pz-check" ${res.complete?'':'disabled'}>${icon('check')} Kijk na</button></div>`}</div></section><div class="game-buddy">${petImg(p().favorite)}<p><strong>${PETS[p().favorite].name} rekent met je mee.</strong><br>Foutje? Daar leer je juist van!</p></div>`;}
function checkAnswer(){if(!round||round.done)return;const q=round.q,st=round.st,res=PZ.check(q,st),maxTries=3;if(!res.complete){round.feedback=q.cells.length?'Vul eerst alle vakjes in.':'Maak de opdracht eerst af.';render();return;}
for(const c of q.cells){if(st.marks[c.id]==='shown')continue;if(res.bad.includes(c.id))st.marks[c.id]='bad';else if(!q.ruleCheck)st.marks[c.id]='ok';}st.xBad=!res.xok;
if(res.ok){round.done=true;st.locked=true;for(const c of q.cells)if(st.marks[c.id]!=='shown')st.marks[c.id]='ok';const first=round.mistakes===0&&!round.helped,ms=Date.now()-round.qStart;learn(q,LM.scoreOf({frac:round.mistakes?round.firstFrac:1,hint:round.preHint,solved:true,fact:isFact(q),ms:ms/Math.max(1,q.table?q.cells.length:1)}),ms,{table:round.tableMode,ok:first,review:round.review,check:round.mode==='check'});if(first)round.correct++;if(round.mistakes||round.preHint>=2)queueTwin(q);round.lastSpoken=`${round.mistakes?'Goed doorgezet!':'Helemaal goed!'} ${round.mistakes?CO.steps(q).join('. '):q.explanation} Druk op de paarse pijl om verder te gaan.`;save();sound('correct');render();speak(round.lastSpoken);return;}
if(!round.mistakes)round.firstFrac=q.cells.length>1&&!q.ruleCheck?Math.max(0,1-res.bad.length/q.cells.length):0;round.mistakes++;round.helped=true;round.hint=true;round.hintLevel=Math.max(round.hintLevel,Math.min(round.mistakes,2));round.diag=res.bad.length?CO.diagnose(q,st):!res.xok?CO.diagnoseX(q,st):null;if(round.diag)noteErr(round.diag.code);const n=res.bad.length;round.feedback=round.diag&&q.cells.length<=1?'Probeer het nog eens.':n?`${n===1?'Eén vakje klopt':n+' vakjes kloppen'} nog niet. ${n===1?'Verbeter het oranje vakje.':'Verbeter de oranje vakjes.'}`:'Dat klopt nog niet helemaal. Kijk nog eens goed.';if(res.bad[0])st.active=res.bad[0];
if(round.mistakes>=maxTries){round.done=true;round.revealed=true;PZ.reveal(q,st);st.locked=true;learn(q,LM.scoreOf({frac:round.firstFrac,hint:round.preHint}),Date.now()-round.qStart,{table:round.tableMode,ok:false,revealed:true,review:round.review,check:round.mode==='check'});queueTwin(q);round.lastSpoken=`We doen deze samen. ${CO.steps(q).join('. ')} Druk op de paarse pijl om verder te gaan.`;save();render();speak(round.lastSpoken);}else{save();render();speak(`Bijna. ${round.diag?round.diag.text:hintText()} Probeer het nog eens.`);}}
function next(){if(page!=='play'||!round?.done)return;if(round.index===round.len-1){if(round.mode==='check'){const u=U();u.checks.push({date:new Date().toISOString().slice(0,10),levels:Object.fromEntries(WKEYS.map(k=>[k,Math.round(LM.mastery(u.skill[k])*100)/100])),correct:round.correct});u.checks=u.checks.slice(-20);toast('Niveaucheck klaar! Het rapport voor papa en mama is bijgewerkt.');}pending={...reward(p()),score:round.correct,revealed:false,trade:false,replay:{mode:'practice',topic:round.focus,tableMode:round.tableMode,table:round.table}};p().favorite=pending.pet.id;page='reward';save();render();speak(`Je hebt ${['nul','een','twee','drie','vier','vijf','zes','zeven','acht','negen','tien','elf','twaalf'][round.len]||round.len} opdrachten gemaakt! Je ei is klaar. Tik op het ei om je vriendje te ontdekken.`);return;}round.index++;newQ();render();if(supportsVoice)speechSynthesis.cancel();speak(round.q.spoken);}
function rewardScreen(){
 const secret=pending.pet.rarity==='secret',stage=pending.hatchStage||0;
 const suspense=['Ssst… er beweegt iets!','Kijk, het begint te stralen!','Bijna… wie zou het zijn?'];
 return `<section class="reward-screen ${pending.revealed&&secret?'secret-celebration':''}"><div class="eyebrow">${pending.revealed&&secret?'✦ SECRET ONTDEKT ✦':'AVONTUUR VOLTOOID'}</div><h1>${pending.revealed?`Hallo, ${pending.pet.name}!`:pending.hatching?suspense[Math.min(stage,2)]:'Er beweegt iets in je ei…'}</h1><p>${pending.revealed?pending.pet.tag:pending.trade?'Vier exemplaren geruild. Wie krijg je terug?':`Een ei uit ${pending.group.name}. Helemaal voor jou.`}</p>${pending.revealed?`<div class="pet-reveal ${secret?'secret-reveal':''}" style="--family-color:${pending.group.color};--family-tint:${pending.group.tint}">${petImg(pending.pet.id)}<span class="reveal-star one">✦</span><span class="reveal-star two">✦</span>${secret?'<span class="reveal-star three">✧</span><span class="reveal-star four">✦</span>':''}<span class="rarity-label ${pending.pet.rarity}">${pending.isNew?'NIEUW · ':'DUBBEL · '}${pending.pet.kind}</span></div><div class="reward-family"><strong>${pending.group.name}</strong><span>${groupProgress(p(),pending.group.id)} / 10 ontdekt</span><progress max="10" value="${groupProgress(p(),pending.group.id)}" aria-label="Voortgang ${pending.group.name}"></progress>${pending.groupComplete?`<span class="family-complete">${icon('check')} Groep compleet!</span>`:''}</div>`:`<button class="hatch-button ${pending.hatching?'hatching stage-'+stage:''}" data-action="hatch" aria-label="${pending.hatching?'Je ei komt uit. Nog heel even!':'Open je verrassingsei'}" ${pending.hatching?'disabled':''}><span class="hatch-egg">🥚</span><span class="hatch-spark hs1" aria-hidden="true">✦</span><span class="hatch-spark hs2" aria-hidden="true">✦</span><span class="hatch-spark hs3" aria-hidden="true">✧</span><span class="hatch-label">${pending.hatching?'Nog héél even…':'Tik om te openen'} ${icon('sparkles')}</span></button>${pending.hatching?`<div class="hatch-steps" aria-hidden="true">${[0,1,2].map(i=>`<i class="${i<=stage?'lit':''}"></i>`).join('')}</div>`:''}`}<div class="reward-stats">${pending.trade?`<span>${icon('sparkles')} 4 → 1 geruild</span>`:`<span>${icon('star')} +6 sterren</span><span>${icon('check')} ${pending.score} zonder hulp</span>`}</div>${pending.revealed?`<div class="copy-reward"><strong>${pending.isNew?'Een nieuwe ontdekking!':`Je hebt nu ${ownedCount(p(),pending.pet.id)} × ${pending.pet.name}`}</strong><p>${pending.isNew?'Je verzameling groeit.':'Vier dezelfde kun je ruilen voor een ontbrekend beestje uit deze groep.'}</p></div>`:''}${pending.revealed?`<div class="reward-actions"><button class="button yellow big reward-again" data-action="reward-again">${icon('play')} Nog een ronde</button><button class="button secondary" data-action="reward-group">${icon('heart')} Bekijk deze groep</button><button class="button secondary" data-action="share">${icon('share')} Laat je vriendjes zien</button><button class="text-button" data-action="nav" data-page="home">Terug naar je avonturen</button></div>`:'<p class="small-note">Je vriendje is al voor je bewaard.</p>'}</section>`;
}
function hatch(){
 if(!pending||pending.revealed||pending.hatching)return;
 const egg=pending;egg.hatching=true;egg.hatchStage=0;render();speak('Ssst. Wie zou er in jouw ei zitten?');hatchTone(0);
 const later=(fn,ms)=>setTimeout(()=>{if(pending===egg&&page==='reward')fn();},ms);
 later(()=>{egg.hatchStage=1;render();hatchTone(1);},1250);
 later(()=>{egg.hatchStage=2;render();hatchTone(2);},2500);
 later(()=>{egg.hatching=false;egg.revealed=true;sound('win');render();speak(`${egg.pet.rarity==='secret'&&egg.isNew?'Wauw! Je hebt een geheim vriendje ontdekt! ':''}Daar is ${egg.pet.name}! ${egg.pet.tag}${!egg.isNew?' Je hebt dit vriendje nu '+ownedCount(p(),egg.pet.id)+' keer. Vier dezelfde kun je ruilen.':''}`);},4000);
}
function hatchTone(stage){if(!voice)return;try{audioContext ||= new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();[0,1,2].slice(0,stage+1).forEach((n)=>{const at=audioContext.currentTime+n*.13,o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.setValueAtTime(220+stage*160,at);o.frequency.exponentialRampToValueAtTime(330+stage*220,at+.22);g.gain.setValueAtTime(.0001,at);g.gain.exponentialRampToValueAtTime(.045,at+.025);g.gain.exponentialRampToValueAtTime(.0001,at+.35);o.connect(g);g.connect(audioContext.destination);o.start(at);o.stop(at+.36);});}catch{}}
function groupCard(group){const found=groupProgress(p(),group.id),secret=p().pets.includes(group.id*10+9);return `<button class="family-card ${found===10?'completed':''}" data-action="group" data-group="${group.id}" style="--family-color:${group.color};--family-tint:${group.tint}" aria-label="${group.name}, ${found} van 10 ontdekt"><div class="family-art">${petImg(group.id*10,'family-front')}${petImg(group.id*10+7,'family-back')}<span class="family-number">${String(group.id+1).padStart(2,'0')}</span>${p().eggGroup===group.id?'<span class="chosen-egg">🥚 Jouw ei</span>':''}</div><div class="family-body"><h2>${group.name}</h2><p>${group.description}</p><div class="family-count"><span>${found} / 10 ontdekt</span><span class="secret-indicator ${secret?'found':''}">${icon(secret?'sparkles':'lock')} ${secret?'Secret gevonden':'1 secret'}</span></div><progress max="10" value="${found}" aria-label="${found} van 10"></progress></div></button>`;}
function bookCard(pet,shared=false){const owned=shared||p().pets.includes(pet.id),hidden=pet.rarity==='secret'&&!owned,group=GROUPS[pet.group];return `<button class="book-card ${owned?'discovered':'undiscovered'} ${hidden?'secret-hidden':''} ${pet.rarity} ${!shared&&p().favorite===pet.id?'is-favorite':''}" data-action="${shared?'shared-pet':'pet'}" data-id="${pet.id}" style="--family-color:${group.color};--family-tint:${group.tint}" aria-label="${hidden?'Geheim vriendje uit '+group.name:pet.name+', '+(owned?'gevonden':'nog in het ei')}"><div class="book-card-top"><span class="catalog-number">#${String(pet.id+1).padStart(3,'0')}</span><span class="rarity-label ${pet.rarity}">${hidden?icon('lock'):icon(pet.rarity==='secret'?'sparkles':pet.rarity==='rare'?'star':'heart')}${pet.kind}</span></div><div class="book-art">${hidden?'<span class="secret-question">?</span><span class="secret-glint">✦</span>':petImg(pet.id)}${owned?`<span class="owned-check">${icon(!shared&&p().favorite===pet.id?'heart':'check')}</span>`:`<span class="not-found">${icon('lock')} Nog in het ei</span>`}</div><div class="book-card-body">${owned&&!shared?`<span class="copy-count ${ownedCount(p(),pet.id)>=4?'trade-ready':''}">${ownedCount(p(),pet.id)}× ${ownedCount(p(),pet.id)>=4?'· Ruilen':''}</span>`:''}<span class="pet-family-name">${group.name}</span><h3>${hidden?'Een groot geheim':pet.name}</h3><p>${hidden?'Wie verstopt zich hier?':pet.tag}</p></div></button>`;}
function galleryTools(){return `<div class="gallery-tools"><div class="gallery-views" aria-label="Weergave">${[['worlds','Werelden','map'],['all','Alle beestjes','grid'],['owned','Gevonden','heart'],['duplicates','Dubbelen','grid'],['secrets','Secrets','sparkles']].map(([v,n,i])=>`<button data-action="gallery-view" data-view="${v}" class="${gallery.view===v&&gallery.group===null?'active':''}" aria-pressed="${gallery.view===v&&gallery.group===null}">${icon(i)}${n}</button>`).join('')}</div><div class="gallery-search"><label><span class="sr-only">Zoek een groep of beestje</span><input id="gallery-search" type="search" placeholder="Zoek een groep of beestje…" value="${escapeHTML(gallery.query)}" autocomplete="off"></label><button class="icon-button" data-action="gallery-listen" aria-label="Lees de uitleg van het vriendjesboek voor">${icon('volume')}</button></div></div>`;}
function galleryResults(){const q=gallery.query.trim().toLocaleLowerCase('nl');
 if(gallery.view==='worlds'&&gallery.group===null){const groups=GROUPS.filter(g=>`${g.name} ${g.description}`.toLocaleLowerCase('nl').includes(q));return groups.length?`<div class="family-grid">${groups.map(groupCard).join('')}</div>`:emptyGallery();}
 const filter=pet=>{const owned=p().pets.includes(pet.id),hidden=pet.rarity==='secret'&&!owned;return (gallery.group===null||pet.group===gallery.group)&&(gallery.view!=='owned'||owned)&&(gallery.view!=='duplicates'||ownedCount(p(),pet.id)>1)&&(gallery.view!=='secrets'||pet.rarity==='secret')&&(gallery.filter==='all'||pet.rarity===gallery.filter)&&(!q||`${hidden?'secret geheim':pet.name} ${GROUPS[pet.group].name}`.toLocaleLowerCase('nl').includes(q));};
 const pets=PETS.filter(filter),pages=Math.max(1,Math.ceil(pets.length/30));gallery.page=Math.min(gallery.page,pages);
 return `<div class="book-result-bar"><span>${pets.length} ${pets.length===1?'beestje':'beestjes'}</span><label>Zeldzaamheid <select id="rarity-filter" aria-label="Filter op zeldzaamheid">${[['all','Alles'],['common','Gewoon'],['rare','Zeldzaam'],['secret','Secret']].map(([v,n])=>`<option value="${v}" ${gallery.filter===v?'selected':''}>${n}</option>`).join('')}</select></label></div>${pets.length?`<div class="book-grid">${pets.slice((gallery.page-1)*30,gallery.page*30).map(pet=>bookCard(pet)).join('')}</div>`:emptyGallery()}${pages>1?`<div class="book-pagination"><button class="button secondary" data-action="gallery-page" data-delta="-1" ${gallery.page===1?'disabled':''}>${icon('back')} Vorige</button><span>Pagina ${gallery.page} van ${pages}</span><button class="button secondary" data-action="gallery-page" data-delta="1" ${gallery.page===pages?'disabled':''}>Volgende ${icon('arrow')}</button></div>`:''}`;
}
function emptyGallery(){return `<div class="book-empty">${icon('sparkles')}<h2>Hier is het nog even stil</h2><p>Probeer een andere zoekopdracht of ontdek een nieuw vriendje.</p><button class="button purple" data-action="gallery-reset">Toon alle werelden</button></div>`;}
function collection(){const stats=collectionStats(p()),group=gallery.group===null?null:GROUPS[gallery.group];return `<div class="page-heading book-heading"><div><div class="eyebrow">20 WERELDEN · 200 VRIENDJES · 20 SECRETS</div><h1>Het grote vriendjesboek <span class="heading-star">✦</span></h1><p>Een wereld vol wezentjes. En geheimen om te ontdekken.</p></div><button class="button purple" data-action="share">${icon('share')} Deel mijn boek</button></div>${group?`<section class="group-banner" style="--family-color:${group.color};--family-tint:${group.tint}"><div><button class="text-button" data-action="gallery-reset">${icon('back')} Alle werelden</button><span class="eyebrow">WERELD ${String(group.id+1).padStart(2,'0')}</span><h2>${group.name}</h2><p>${group.description}</p><div class="group-meta"><span>${groupProgress(p(),group.id)} / 10 ontdekt</span><span>${p().pets.includes(group.id*10+9)?'✦ Secret gevonden':'✧ Eén verborgen secret'}</span></div><button class="button purple" data-action="choose-egg" data-group="${group.id}">${groupProgress(p(),group.id)===10?icon('check'):p().eggGroup===group.id?icon('check'):'🥚'} ${p().eggGroup===group.id?'Dit is jouw ei':'Kies dit ei'}</button></div><div class="group-banner-art">${petImg(group.id*10+7)}${petImg(group.id*10)}</div></section>`:`<section class="book-hero"><div><span class="pill pale">${icon('heart')} JOUW VERZAMELING</span><h2>Elk ei een nieuw verhaal.</h2><p>Kies een wereld, oefen zes sommen<br>en ontdek wie er op je wacht.</p><div class="book-totals"><div><strong>${stats.found}<small> / 200</small></strong><span>Vriendjes</span></div><div><strong>${stats.complete}<small> / 20</small></strong><span>Groepen compleet</span></div><div><strong>${stats.secrets}<small> / 20</small></strong><span>Secrets ontdekt</span></div></div></div><div class="book-hero-pet">${petImg(p().favorite)}<span>${PETS[p().favorite].name} · jouw maatje</span></div></section>`}${galleryTools()}<div id="gallery-results">${galleryResults()}</div><div class="collection-note">${icon('sparkles')} Elke wereld heeft 7 gewone, 2 zeldzame en 1 geheime vriend. Je kunt dezelfde vaker vinden. Vier dezelfde ruil je voor een ontbrekend beestje uit die groep.</div>`;}
function refreshGallery(){const container=$('#gallery-results');if(container)container.innerHTML=galleryResults();}
function openGroup(id){if(!GROUPS[id])return;gallery={view:'all',group:id,query:'',filter:'all',page:1};page='collection';render();window.scrollTo(0,0);speak(`${GROUPS[id].name}. ${groupProgress(p(),id)} van de tien vriendjes ontdekt. Tik op kies dit ei om vriendjes uit deze groep te vinden.`);}
function chooseEgg(id){if(!GROUPS[id])return;p().eggGroup=id;save();gallery.group=id;gallery.view='all';page='collection';render();toast(`Jouw volgende ei: ${GROUPS[id].name}`);speak(`Je hebt het ei van ${GROUPS[id].name} gekozen. Speel zes sommen om een vriendje te ontdekken.`);}
function progress(){const u=U(),profile=p(),total=Object.values(profile.stats).reduce((s,v)=>s+v.attempted,0);return `<div class="page-heading"><div><div class="eyebrow">KIJK HOE JE GROEIT</div><h1>Stapje voor stapje slimmer</h1><p>Jouw eigen pad. Op jouw eigen tempo.</p></div>${petImg(profile.favorite,'progress-pet')}</div><div class="growth-stats"><div>${icon('flag')}<strong>${profile.rounds}</strong><span>Avonturen beleefd</span></div><div>${icon('check')}<strong>${total}</strong><span>Opdrachten geoefend</span></div><div>${icon('heart')}<strong>${profile.pets.length}</strong><span>Vriendjes gevonden</span></div></div>${goalCard(u)}<section class="growth-list">${WKEYS.map(key=>{const t=TOPICS[key],sk=u.skill[key],M=LM.mastery(sk),sec=LM.secured(sk),known=sk.n>=5&&LM.sd(sk)<1,li=LM.levelInfo(sec),fill=known?Math.max(0,Math.min(12,Math.floor(sec))):0,soon=Math.max(fill,Math.min(12,Math.floor(M)));return `<div class="growth-row"><span class="world-icon ${t.color}">${icon(t.icon)}</span><div><h2>${wname(key)}</h2><p>${sk.n?`${sk.n} opdrachten geoefend`:'Dit avontuur staat voor je klaar'}</p></div><div class="level-block"><span>${known?`${li.label} ${icon('check')}`:'Aan het ontdekken'}</span><div class="level-dots twelve">${Array.from({length:12},(_,i)=>`<i class="${i<fill?'filled':i<soon?'soon':''} ${i%2?'':'gstart'}"></i>`).join('')}</div></div><button class="icon-button" data-action="start" data-topic="${key}" aria-label="Speel ${wname(key)}">${icon('play')}</button></div>`;}).join('')}</section><div class="growth-actions"><button class="button purple" data-action="check-start">${icon('flag')} Doe de niveaucheck</button><button class="button secondary" data-action="nav" data-page="report">Rapport voor papa en mama ${icon('arrow')}</button></div><div class="arena-record">${icon('sparkles')} Rekenarena: ${profile.battleStats?.played||0} duels gespeeld · ${profile.battleStats?.wins||0} gewonnen</div><div class="collection-note">${icon('bulb')} Volle stipjes heb je echt binnen, die raak je nooit meer kwijt. Lichte stipjes ben je nu aan het veroveren. Een foutje is niet erg: daar leer je van.</div>`;}
const sharedIds=parseSharedPets(location.hash);
function sharedView(){const groups=GROUPS.filter(g=>g.petIds.some(id=>sharedIds.includes(id)));return `<div class="page-heading"><div><div class="eyebrow">GROETJES UIT REKENRIJK</div><h1>Een boek vol vriendjes!</h1><p>Een vriend deelt ${sharedIds.length} ontdekte beestjes met jou.</p></div></div>${groups.map(group=>`<section class="shared-family"><div class="section-title"><h2>${group.name}</h2><span>${group.petIds.filter(id=>sharedIds.includes(id)).length} / 10</span></div><div class="book-grid">${group.petIds.filter(id=>sharedIds.includes(id)).map(id=>bookCard(PETS[id],true)).join('')}</div></section>`).join('')}<div class="share-start"><h2>Welke vriendjes ontdek jij?</h2><button class="button yellow big" data-action="nav" data-page="home">${icon('play')} Mijn eigen avontuur</button></div>`;}
function modal(html){const d=$('#modal');d.innerHTML=`<button class="modal-close icon-button" data-action="close" aria-label="Sluiten">${icon('close')}</button>${html}`;d.showModal();}
function showPet(id,shared=false){if(!PETS[id])return;const pet=PETS[id],group=GROUPS[pet.group],owned=shared||p().pets.includes(id),hidden=pet.rarity==='secret'&&!owned;modal(`<div class="pet-detail book-detail ${hidden?'hidden-detail':''}" style="--family-color:${group.color};--family-tint:${group.tint}">${hidden?'<div class="detail-mystery">? <span>✦</span></div>':petImg(id)}<span class="rarity-label ${pet.rarity}">${pet.kind}</span><span class="detail-group">${group.name} · #${String(id+1).padStart(3,'0')}</span><h2>${hidden?'Een verborgen geheim':pet.name}</h2><p>${hidden?group.clue:pet.tag}</p>${hidden?`<div class="secret-clue">${icon('bulb')} Dit zeldzame vriendje kan in elk ei van deze groep zitten. Of ruil vier dezelfde voor een ontbrekend vriendje: ook een secret kan dan verschijnen!</div>`:''}${owned&&!shared?`<div class="pet-inventory"><strong>${ownedCount(p(),id)} exemplaren</strong><span>${ownedCount(p(),id)>=4?'Vier klaar om te ruilen':`Nog ${4-ownedCount(p(),id)} voor een ruil`}</span></div><button class="button purple" data-action="favorite" data-id="${id}">${icon('heart')} ${p().favorite===id?'Dit is mijn maatje':'Kies als mijn maatje'}</button><button class="button secondary trade-button" data-action="trade-preview" data-id="${id}" ${ownedCount(p(),id)<4||!tradeOptions(p(),id).length?'disabled':''}>${icon('sparkles')} Ruil 4 voor 1 nieuw vriendje</button>${!tradeOptions(p(),id).length?'<span class="small-note">Deze groep is compleet. Er is geen ontbrekend vriendje om voor te ruilen.</span>':''}`:!shared?`<button class="button purple" data-action="choose-egg" data-group="${group.id}">🥚 Kies het ei van deze groep</button>`:''}<button class="text-button" data-action="pet-listen" data-id="${id}" data-shared="${shared}">${icon('volume')} Luister naar dit vriendje</button></div>`);speak(hidden?`Dit vriendje is geheim. Een hint: ${group.clue} Ontdek vriendjes uit deze groep, dan komt het geheim tevoorschijn.`:`Dit is ${pet.name}. ${pet.tag}${!owned?' Je vindt dit vriendje in het ei van '+group.name+'.':''}`);}
function parents(){const stats=Object.values(p().stats),n=stats.reduce((a,s)=>a+s.attempted,0),c=stats.reduce((a,s)=>a+s.correct,0);modal(`<div class="parent-panel"><span class="eyebrow">VOOR OUDERS</span><h2>Spelen. Proberen. Begrijpen.</h2><p>Maak voor elk kind een eigen speler met naam en groep (3 t/m 8). Elke speler heeft een eigen verzameling en een eigen rekenniveau per wereld.</p><h3>Zo leert het spel mee</h3><p>Elke wereld heeft per speler een vaardigheidsscore. Na elk antwoord past die zich aan: in het begin met grote stappen, zodat het spel snel het goede niveau vindt, en zonder plafond. Het spel kiest opdrachten waarvan je kind er ongeveer 3 van de 4 goed heeft. Fouten komen later terug als herhaling. In het gewone avontuur is er geen tijdslimiet.</p><p><strong>${escapeHTML(U().name)}:</strong> ${n} opdrachten geoefend, ${c} direct goed zonder hulp${n?` (${Math.round(c/n*100)}%)`:''}. Dit is een oefenoverzicht, geen schooltoets.</p><h3>Rapport en spelers</h3><p>Het rapport laat per wereld zien op welk niveau ${escapeHTML(U().name)} nu werkt, vergeleken met wat je in deze maand van het schooljaar mag verwachten. Ook zie je de groei, sterke en zwakke onderdelen en hoe vlot de tafels gaan.</p><div class="parent-buttons"><button class="button purple" data-action="nav" data-page="report">Open het rapport</button><button class="button secondary" data-action="players">Spelers beheren</button></div><h3>App op je telefoon</h3><p>Zet RekenRijk op het beginscherm. Open het spel eerst online om solo ook zonder internet te spelen. Online duels hebben internet nodig.</p><button class="button secondary" data-action="pwa-install">Installeer RekenRijk</button><h3>Stem en bewaren</h3><p>Opdrachten en hulp worden in het Nederlands voorgelezen na een tik. De stem komt van je apparaat. Zorg dat een Nederlandse stem beschikbaar is en het volume aanstaat.</p><p>Voortgang en beide verzamelingen blijven in deze browser, op dit apparaat. Ze gaan niet automatisch mee naar een ander apparaat. Een verzamellink bevat alleen de gekozen vriendjes, geen naam of leerscores. Een duel deelt alleen het gekozen beestje, het rekenniveau en de duelgegevens. PeerJS helpt de apparaten verbinden; daarna loopt het duel via WebRTC. Op sommige netwerken kan verbinden mislukken. Er is geen chat, camera of microfoon.</p><h3>Een eerlijke verrassing</h3><p>Er zijn 20 groepen met elk 10 vriendjes: 7 gewone, 2 zeldzame en 1 secret. Kies een groeps-ei in het vriendjesboek. Elke voltooide ronde geeft een willekeurig exemplaar uit de gekozen groep. Dubbele vondsten tellen mee. De kansverdeling per ei is 77% gewoon, 20% zeldzaam en 3% secret, daarna heeft elk beestje binnen die klasse dezelfde kans. Je kunt vier exemplaren van hetzelfde beestje ruilen voor één willekeurig ontbrekend beestje uit dezelfde groep. Ook secrets kunnen uit een ruil komen; alle ontbrekende beestjes hebben bij een ruil dezelfde kans. De vier exemplaren worden ingeleverd. Houd je er nul over, dan verdwijnt dat beestje uit je actieve verzameling. De ruilknop laat dit vooraf zien. Geen aankopen, reclame of dagelijkse verplichtingen.</p><h3>Kangoeroe</h3><p>Puzzels in de stijl van de Kangoeroewedstrijd: wizFUN voor groep 3 en 4, wizKID voor groep 5 en 6. Geen opgaven uit het archief, maar nieuwe opgaven per patroon. Oefenen kiest steeds het zwakste patroon; de wedstrijd lijkt op het echte blad en toont de score per puzzelsoort.</p><button class="button secondary" data-action="kg-parents">Bekijk beheersing per patroon</button><h3>De rekensprint</h3><p>Kies 1, 2 of 3 minuten en één of meerdere soorten sommen. Elk antwoord telt één keer; ook na een fout ga je direct door. Je krijgt één ei bij minstens één goed antwoord en maximaal één fout. Vanaf twee fouten is er geen ei. De klok loopt door bij voorlezen en in een ander tabblad. Na het openen van het ei start Nog een ronde direct met dezelfde instellingen.</p><h3>De rekenarena</h3><p>Speel om de beurt op één apparaat, of tegelijk op twee apparaten via een kamercode of uitnodigingslink. Ieder krijgt sommen op het eigen niveau. Online heb je 30 seconden per som; zonder antwoord doe je geen schade. Houd beide schermen open. Een verbroken verbinding sluit de kamer. Alle beestjes starten met 100 energie. Een goed antwoord geeft 10 schade, met tot 12 snelheidsbonus en tot 6 combobonus. De klok start zodra de som verschijnt. Voorlezen is optioneel en pauzeert de klok niet. Beide aanvallen raken tegelijk, zodat de eerste speler geen extra beurt krijgt. Een duel duurt maximaal vijf rondes. Beide spelers krijgen sterren; er verdwijnen geen beestjes.</p><button class="button purple" data-action="close">Helder, terug naar het avontuur</button></div>`);}
async function share(){const url=new URL(location.href);url.search='';url.hash=`vriendjes=${p().pets.join(',')}`;const payload={title:'Mijn vriendjes in RekenRijk',text:'Kijk welke vriendjes ik heb ontdekt! Welke vind jij?',url:url.href};if(navigator.share){try{await navigator.share(payload);return;}catch(e){if(e.name==='AbortError')return;}}try{await navigator.clipboard.writeText(url.href);toast('Link gekopieerd! Plak hem in een berichtje.');speak('De link is gekopieerd. Vraag een volwassene om hem naar je vrienden te sturen.');}catch{modal(`<h2>Deel je vriendjes</h2><p>Kopieer deze link en stuur hem naar je vrienden.</p><label class="share-label">Jouw verzameling<input id="share-url" readonly></label><button class="button purple" data-action="select-link">Selecteer link</button>`);$('#share-url').value=url.href;}}
function go(target){if(!['home','collection','progress','battle','sprint','report','kangoeroe','leger','ster'].includes(target))return;if(page==='leger'&&leger.active()&&target!=='leger'){exitRound(()=>{leger.handle({dataset:{action:'lg-quit-yes'}});page=target;render();});return;}if(page==='play'){exitRound(()=>{page=target;render();});return;}if(page==='sprint'){if(sprint.active()){exitRound(()=>{sprint.stop();page=target;render();});return;}sprint.stop();}if(page==='battle')arena.stop();if(supportsVoice)speechSynthesis.cancel();page=target;render();window.scrollTo(0,0);if(target==='home')speak('Tik op de gele speelknop voor jouw eigen avontuur.');if(target==='battle')speak('Welkom in de rekenarena. Kies allebei een beestje en tik op klaar voor het duel.');if(target==='collection')speak(`Je hebt ${p().pets.length} vriendjes. Tik op een vriendje om het te kiezen.`);}
function exitRound(done){modal(`<div class="exit-panel"><span class="exit-egg" aria-hidden="true">🥚</span><h2>Even stoppen?</h2><p>Je oefenstappen zijn bewaard. Voor je ei moet je deze ronde nog afmaken.</p><button class="button purple" data-action="close">${icon('play')} Verder spelen</button><button id="confirm-exit" class="button secondary">Terug naar avonturen</button></div>`);$('#confirm-exit').onclick=()=>{if(supportsVoice)speechSynthesis.cancel();done();};speak('Wil je stoppen? Tik op de paarse knop om verder te spelen.');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;if(page==='leger'&&leger.handle(b))return;if(page==='ster'&&ster.handle(b))return;if(page==='sprint'&&sprint.handle(b))return;if(kanga.handle(b))return;if(arena.handle(b))return;const action=b.dataset.action;switch(action){case'nav':go(b.dataset.page);break;case'voice':voice=!voice;if(!voice&&supportsVoice)speechSynthesis.cancel();save();render();arena.voiceChanged();if(voice&&page!=='battle')speak(page==='play'?round.q.spoken:'Het geluid staat aan. Met de luisterknop lees ik de som voor.');break;case'welcome':speak('Welkom in RekenRijk! Tik op de grote gele speelknop. We maken zes sommen. Dan komt er een vriendje uit jouw ei!',true);break;case'start':start(b.dataset.topic);break;case'pz-cell':if(page==='play'&&round&&!round.done){round.st.active=b.dataset.cell;render();}break;case'pz-key':if(page==='play'&&round&&!round.done&&PZ.input(round.q,round.st,b.dataset.k)){round.feedback='';render();}break;case'pz-x':if(page==='play'&&round&&!round.done&&PZ.act(round.q,round.st,b.dataset.op,b.dataset.a)){round.feedback='';render();sound('tap');}break;case'pz-check':if(page==='play')checkAnswer();break;case'next':next();break;case'repeat':speak(round.done?round.lastSpoken:round.q.spoken,true);break;case'hint':if(!round||round.done||round.hintLevel>=3)break;round.hintLevel++;if(!round.mistakes)round.preHint=Math.max(round.preHint||0,round.hintLevel);round.hint=true;round.helped=true;if(round.hintLevel===3)applyFirstStep();render();speak(hintText(),true);break;case'exit':exitRound(()=>{page='home';round=null;render();});break;case'hatch':hatch();break;case'pet':showPet(Number(b.dataset.id));break;case'shared-pet':showPet(Number(b.dataset.id),true);break;case'favorite':if(!p().pets.includes(Number(b.dataset.id)))break;p().favorite=Number(b.dataset.id);save();render();toast(`${PETS[p().favorite].name} gaat met je mee!`);break;case'parents':parents();break;
case'reward-again':{if(page!=='reward'||!pending?.revealed)break;const replay=pending.replay;pending=null;if(replay?.mode==='sprint'){page='sprint';sprint.start(replay.settings);}else if(replay?.mode==='leger'){page='leger';}else if(replay?.mode==='ster'){page='ster';}else start(replay?.topic||'mix',replay?.tableMode||false,replay?.table??null);break;}
case'table-picker':tablePicker();break;
case'players':playersModal();break;
case'sync-add':syncDo('#sync-join',null);break;
case'sync-link':syncDo('#sync-link',b.dataset.id);break;
case'player-pick':pickPlayer(b.dataset.id);break;
case'player-new':playerForm(null);break;
case'player-edit':playerForm(b.dataset.id);break;
case'player-pace':form.pace=b.dataset.pace;document.querySelectorAll('[data-action=player-pace]').forEach(x=>x.classList.toggle('selected',x.dataset.pace===form.pace));break;case'goal-pick':pickGoal(Number(b.dataset.i));break;case'player-groep':form.groep=Number(b.dataset.g);document.querySelectorAll('[data-action=player-groep]').forEach(x=>x.classList.toggle('selected',Number(x.dataset.g)===form.groep));break;
case'player-save':savePlayer();break;
case'player-delete':deletePlayer(b);break;
case'player-reset':resetLevel(b);break;
case'check-start':if($('#modal').open)$('#modal').close();start('mix',false,null,'check');break;
case'report-print':window.print();break;
case'table-start':start('tables',true,b.dataset.table==='mix'?null:Number(b.dataset.table));break;
case'trade-preview':previewTrade(Number(b.dataset.id));break;
case'trade-confirm':confirmTrade(Number(b.dataset.id));break;
case'group':openGroup(Number(b.dataset.group));break;
case'choose-egg':chooseEgg(Number(b.dataset.group));break;
case'egg-picker':gallery={view:'worlds',group:null,query:'',filter:'all',page:1};go('collection');break;
case'reward-group':openGroup(pending.group.id);break;
case'gallery-view':gallery={view:b.dataset.view,group:null,query:'',filter:'all',page:1};render();break;
case'gallery-reset':gallery={view:'worlds',group:null,query:'',filter:'all',page:1};render();break;
case'gallery-page':gallery.page+=Number(b.dataset.delta);refreshGallery();$('#gallery-results').scrollIntoView({block:'start'});break;
case'gallery-listen':speak('Welkom in je vriendjesboek. Er zijn twintig werelden met elk tien vriendjes. Tik op een wereld om de beestjes te bekijken. Tik op kies dit ei om vriendjes uit die wereld te ontdekken.',true);break;
case'pet-listen':{const pet=PETS[Number(b.dataset.id)];if(pet){const hidden=pet.rarity==='secret'&&!p().pets.includes(pet.id)&&b.dataset.shared!=='true';speak(hidden?GROUPS[pet.group].clue:`${pet.name}. ${pet.tag}`,true);}break;}
case'close':$('#modal').close();break;case'share':share();break;case'select-link':$('#share-url').select();break;}});
document.addEventListener('input',e=>{if(e.target.id==='gallery-search'){gallery.query=e.target.value;gallery.page=1;refreshGallery();}});
document.addEventListener('change',e=>{if(page==='sprint'&&sprint.change(e.target))return;if(page==='kangoeroe'&&kanga.change(e.target))return;if(arena.change(e.target))return;const key=e.target.dataset.level;if(key&&TOPICS[key]){p().levels[key]=Math.max(1,Math.min(6,Number(e.target.value)));p().streaks[key]=0;p().review=p().review.filter(x=>x.topic!==key);save();}});
document.addEventListener('keydown',e=>{if(page==='ster'&&!$('#modal').open&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)){ster.key(e);return;}if(page==='leger'&&!$('#modal').open&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)){leger.key(e);return;}if(page==='kangoeroe'&&!$('#modal').open&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)){kanga.key(e);return;}if(page==='sprint'&&!$('#modal').open&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)){sprint.key(e);return;}if(page==='battle'&&!$('#modal').open&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)){arena.key(e);return;}if(page!=='play'||!round||$('#modal').open||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;if(e.key==='Enter'){if(document.activeElement.closest('button'))return;e.preventDefault();if(round.done)next();else checkAnswer();return;}if(!round.done&&PZ.onKey(round.q,round.st,e)){round.feedback='';render();}});
syncStart();
if(sharedIds.length)page='shared';else if(location.hash==='#sprint')page='sprint';else if(location.hash==='#boek')page='collection';else if(location.hash==='#arena'||location.hash.startsWith('#duel='))page='battle';render();
if(new URLSearchParams(location.search).has('rrtest'))window.__rrFill=(wrong)=>{if(!round||round.done)return;const q=round.q,st=round.st;for(const c of q.cells)if(st.marks[c.id]!=='ok')st.vals[c.id]=String(wrong?c.answer+1:c.answer);if(q.solution)st.x=wrong?st.x:JSON.parse(JSON.stringify(q.solution));render();};
window.addEventListener('pagehide',()=>{sprint.stop();arena.stop();kanga.stop();if(supportsVoice)speechSynthesis.cancel();});


function playerFields(u){return `<label class="field"><span>Naam</span><input id="player-name" maxlength="20" autocomplete="off" spellcheck="false" value="${u?escapeHTML(u.name):''}" placeholder="Bijvoorbeeld Rafael"></label><div class="field"><span>In welke groep zit ${u?escapeHTML(u.name):'je'}?</span><div class="groep-grid">${[3,4,5,6,7,8].map(g=>`<button type="button" data-action="player-groep" data-g="${g}" class="${form.groep===g?'selected':''}" aria-label="Groep ${g}">Groep<b>${g}</b></button>`).join('')}</div></div>
<div class="field"><span>Hoe moeilijk?</span><div class="pace-grid">${[['rustig','Rustig','Bijna alles lukt. Fijn bij spanning of na een lastige dag.'],['normaal','Normaal','3 van de 4 goed. Zo leer je het meest.'],['uitdaging','Uitdaging','Vaker een stapje te ver. Voor wie van puzzelen houdt.']].map(([k,l,d])=>`<button type="button" data-action="player-pace" data-pace="${k}" class="${form.pace===k?'selected':''}"><b>${l}</b><small>${d}</small></button>`).join('')}</div></div>
<div class="field toggles"><label><input type="checkbox" id="player-read" ${form.read?'checked':''}> <span><b>Lees alles voor</b><small>Elke opdracht wordt automatisch voorgelezen. Fijn bij dyslexie of als lezen nog moeite kost.</small></span></label><label><input type="checkbox" id="player-timer" ${form.timer?'checked':''}> <span><b>Rekensprint met klok</b><small>Uit: de sprint is 20 sommen zonder klok, en je probeert je eigen record te verbeteren.</small></span></label></div>`;}
function onboarding(){if(form.id||!form.pace)form={id:null,groep:form.id?3:form.groep||3,pace:'normaal',read:false,timer:true};return `<div class="onboard"><div class="onboard-card"><span class="brand-mark">${icon('sparkles')}</span><h1>Welkom in RekenRijk</h1><p>Wie gaat er rekenen? Maak een speler aan. Later kun je meer spelers toevoegen: voor elk kind één, elk met een eigen verzameling en een eigen niveau.</p>${playerFields(null)}<button class="button yellow big" data-action="player-save">${icon('play')} Beginnen</button><p class="small-note">Geen account nodig. De voortgang wordt bewaard onder een eigen code, zodat je op elk apparaat verder kunt spelen.</p>${syncJoinHtml()}</div></div><dialog id="modal"></dialog>`;}
function playersModal(){modal(`<div class="players"><span class="eyebrow">WIE SPEELT ER?</span><h2>Kies een speler</h2><div class="player-list">${store.users.map(u=>{const li=LM.levelInfo(overallM(u));return `<div class="player-card ${u.id===U().id?'active':''}"><button class="pick" data-action="player-pick" data-id="${u.id}">${petImg(u.profile.favorite)}<span><strong>${escapeHTML(u.name)}</strong><small>Groep ${u.groep} · werkt op ${li.label.toLowerCase()}</small></span></button><button class="icon-button" data-action="player-edit" data-id="${u.id}" aria-label="Bewerk ${escapeHTML(u.name)}">${icon('settings')}</button></div>`;}).join('')}</div><button class="button purple" data-action="player-new">${icon('plus')} Nieuwe speler</button>${syncJoinHtml()}</div>`);}
function pickPlayer(id){const u=store.users.find(x=>x.id===id);if(!u)return;if(u.id===U().id){$('#modal').close();return;}const change=()=>{sprint.stop();arena.stop();store.rival=store.active;store.active=u.id;if(u.settings?.read)voice=true;page='home';round=null;pending=null;save();render();speak(`Hallo ${u.name}! Tik op de gele knop om te spelen.`);};$('#modal').close();if(page==='play'||(page==='sprint'&&sprint.active()))exitRound(change);else change();}
function playerForm(id){const u=id?store.users.find(x=>x.id===id):null;form={id:u?.id||null,groep:u?u.groep:3,pace:u?.settings?.pace||'normaal',read:!!u?.settings?.read,timer:u?u.settings?.timer!==false:true};modal(`<div class="player-form"><span class="eyebrow">${u?'SPELER BEWERKEN':'NIEUWE SPELER'}</span><h2>${u?escapeHTML(u.name):'Wie gaat er rekenen?'}</h2>${playerFields(u)}<button class="button purple" data-action="player-save">${icon('check')} Bewaar</button>${u?`<p class="small-note">Een andere groep verandert het niveau niet: het spel meet zelf wat ${escapeHTML(u.name)} kan. De groep is het vergelijkpunt in het rapport.</p>${syncPanel(u)}<div class="danger-zone"><button class="text-button" data-action="player-reset" data-id="${u.id}">Niveau opnieuw laten bepalen vanaf groep ${u.groep}</button><button class="text-button danger" data-action="player-delete" data-id="${u.id}">Verwijder speler</button></div>`:''}</div>`);setTimeout(()=>{const el=$('#player-name');if(el&&!u)el.focus();},50);}
function savePlayer(){const el=$('#player-name'),name=(el?.value||'').replace(/[<>&"]/g,'').trim().slice(0,20);if(!name){toast('Vul eerst een naam in.');el?.focus();return;}const g=form.groep>=3&&form.groep<=8?form.groep:3,settings={pace:['rustig','normaal','uitdaging'].includes(form.pace)?form.pace:'normaal',read:!!$('#player-read')?.checked,timer:$('#player-timer')?$('#player-timer').checked:true};if(settings.read)voice=true;
 if(form.id){const u=store.users.find(x=>x.id===form.id);if(!u)return;u.name=name;u.settings=settings;if(u.groep!==g){u.groep=g;if(WKEYS.every(k=>u.skill[k].n===0))u.skill=LM.newSkill(g);}save();if($('#modal').open)$('#modal').close();render();toast(`${name} is bewaard.`);return;}
 if(store.users.length>=30){toast('Er kunnen maximaal 30 spelers op dit apparaat.');return;}
 const u=newUser(name,g);u.settings=settings;syncLevels(u);store.users.push(u);store.rival=store.active;store.active=u.id;page='home';round=null;pending=null;save();if($('#modal').open)$('#modal').close();render();speak(`Welkom ${name}! Tik op de gele knop om te spelen.`);}
function deletePlayer(b){const u=store.users.find(x=>x.id===b.dataset.id);if(!u)return;if(b.dataset.sure!=='1'){b.dataset.sure='1';b.textContent=`Zeker weten? Alle vriendjes en voortgang van ${u.name} verdwijnen. Tik nog eens.`;return;}store.users=store.users.filter(x=>x.id!==u.id);SY?.forget(u.id);if(store.active===u.id)store.active=store.users[0]?.id||null;if(store.rival===u.id)store.rival=null;page='home';round=null;pending=null;save();if($('#modal').open)$('#modal').close();render();toast(`${u.name} is verwijderd.`);}
function resetLevel(b){const u=store.users.find(x=>x.id===b.dataset.id);if(!u)return;if(b.dataset.sure!=='1'){b.dataset.sure='1';b.textContent='Zeker weten? Tik nog eens. De verzameling blijft bewaard.';return;}u.skill=LM.newSkill(u.groep);u.review=[];syncLevels(u);save();if($('#modal').open)$('#modal').close();render();toast(`Het niveau van ${u.name} wordt opnieuw bepaald.`);}
const W_COL={add:'#2f9b6a',tables:'#e8743b',fractions:'#7550ce',life:'#2f80c2',logic:'#d14d84'};
function levelScale(m,exp,iv){const pct=v=>Math.max(0,Math.min(100,(v-.5)/12*100));return `<div class="lvl-scale" role="img" aria-label="Werkniveau op de schaal van groep 3 tot 8">${[3,4,5,6,7,8].map(g=>`<span>${g}</span>`).join('')}${iv?`<em class="band" style="left:${pct(iv[0])}%;width:${pct(iv[1])-pct(iv[0])}%"></em>`:''}<i class="exp" style="left:${pct(exp)}%"></i><b style="left:${pct(m)}%"></b></div>`;}
const sureText=sk=>{const d=LM.sd(sk);return sk.n<3?'nog niet gemeten':d<.55?'zeker':d<.9?'redelijk zeker':'nog onzeker';};
const rangeText=sk=>{const [a,b]=LM.interval(sk),la=LM.levelInfo(a).label,lb=LM.levelInfo(b).label;return la===lb?la:`${la} tot ${lb.toLowerCase()}`;};
function growthChart(u){const all=WKEYS.flatMap(k=>u.skill[k].hist.map(h=>h[0]));const days=[...new Set(all)].sort();if(days.length<2)return '<p class="empty-note">Na een paar dagen oefenen zie je hier de groeilijn per wereld, naast de lijn van wat je voor deze groep mag verwachten.</p>';const first=new Date(days[0]),today=new Date(),span=Math.max(7*864e5,today-first);
 const W=640,H=260,L=56,R=12,T=12,B=28,x=d=>L+(new Date(d)-first)/span*(W-L-R);const vals=WKEYS.flatMap(k=>u.skill[k].hist.map(h=>h[1])).concat([LM.expected(u.groep,first),LM.expected(u.groep,today)]);
 const lo=Math.max(.5,Math.floor(Math.min(...vals)-1)),hi=Math.min(12.5,Math.ceil(Math.max(...vals)+1)),y=v=>T+(H-T-B)*(1-(v-lo)/(hi-lo));
 let g='';for(let k=3;k<=8;k++){const a=2*(k-3)+.5,b=a+2;if(b<lo||a>hi)continue;const y1=y(Math.min(b,hi)),y2=y(Math.max(a,lo));g+=`<rect x="${L}" y="${y1}" width="${W-L-R}" height="${y2-y1}" class="${k%2?'band a':'band b'}"/><text x="${L-8}" y="${(y1+y2)/2+5}" text-anchor="end">gr. ${k}</text>`;}
 const ex=`<line x1="${x(days[0])}" y1="${y(LM.expected(u.groep,first))}" x2="${x(today)}" y2="${y(LM.expected(u.groep,today))}" class="expline"/>`;
 const lines=WKEYS.filter(k=>u.skill[k].hist.length).map(k=>{const h=u.skill[k].hist;const pts=h.map(([d,v])=>`${x(d).toFixed(1)},${y(v).toFixed(1)}`).join(' ');return h.length>1?`<polyline points="${pts}" fill="none" stroke="${W_COL[k]}" stroke-width="3" stroke-linejoin="round"/>`:`<circle cx="${x(h[0][0])}" cy="${y(h[0][1])}" r="4" fill="${W_COL[k]}"/>`;}).join('');
 const lab=`<text x="${L}" y="${H-8}">${first.toLocaleDateString('nl-NL',{day:'numeric',month:'short'})}</text><text x="${W-R}" y="${H-8}" text-anchor="end">vandaag</text>`;
 return `<div class="pz-scroll"><svg class="growth-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Groei van het werkniveau per wereld">${g}${ex}${lines}${lab}</svg></div><div class="chart-legend">${WKEYS.map(k=>`<span><i style="background:${W_COL[k]}"></i>${wname(k)}</span>`).join('')}<span><i class="dash"></i>verwacht voor groep ${u.groep}</span></div>`;}
function report(){const u=U(),now=new Date(),exp=LM.expected(u.groep,now),M=overallM(u),li=LM.levelInfo(M),mo=LM.monthsAhead(M,u.groep,now),answered=WKEYS.reduce((a,k)=>a+u.skill[k].n,0),name=escapeHTML(u.name);
 const chip=m=>m>=3?`<span class="lvl-chip ahead">${m} mnd voor</span>`:m<=-3?`<span class="lvl-chip behind">${-m} mnd achter</span>`:`<span class="lvl-chip on">op niveau</span>`;
 const rows=WKEYS.map(k=>{const sk=u.skill[k],m=LM.mastery(sk),info=LM.levelInfo(m),mm=LM.monthsAhead(m,u.groep,now),sure=' · '+sureText(sk),rng=sk.n>=3?`<small class="rep-range">80% zeker: ${rangeText(sk)}</small>`:'';return `<div class="rep-row"><div class="rep-name"><span class="world-icon ${TOPICS[k].color}">${icon(TOPICS[k].icon)}</span><div><strong>${wname(k)}</strong><small>${sk.n} opdrachten${sure}</small></div></div>${levelScale(m,exp,sk.n>=3?LM.interval(sk):null)}<div class="rep-level"><b>${sk.n?info.label:'Nog niet gemeten'}</b>${rng}${sk.n>=5&&LM.sd(sk)<.9?chip(mm):''}</div></div>`;}).join('');
 const ks=Object.entries(u.kinds).filter(([k,v])=>v.n>=3&&PZ.KIND_NAMES[k]).map(([k,v])=>({k,acc:v.ok/v.n,n:v.n})).sort((a,b)=>b.acc-a.acc);
 const strong=ks.filter(x=>x.acc>=.8).slice(0,4),weak=ks.filter(x=>x.acc<.65).slice(-4).reverse();
 const kl=list=>list.length?`<ul>${list.map(x=>`<li>${PZ.KIND_NAMES[x.k]} <em>${Math.round(x.acc*100)}% goed (${x.n})</em></li>`).join('')}</ul>`:'<p class="empty-note">Nog niet genoeg gegevens.</p>';
 const fcell=(key,label)=>{const st=LM.factState(u.facts[key]);return `<div class="fact ${st}"><b>${label}</b><span>${{vlot:'vlot',bijna:'bijna',oefenen:'oefenen',nieuw:'—'}[st]}</span></div>`;};
 const facts=`<div class="facts">${fcell('tot20','+ en − tot 20')}${Array.from({length:10},(_,i)=>fcell('t'+(i+1),'tafel '+(i+1))).join('')}</div>`;
 const last7=[...Array(7)].map((_,i)=>{const d=new Date(now-i*864e5).toISOString().slice(0,10);return u.days[d]||{n:0,ok:0,ms:0};});const wn=last7.reduce((a,x)=>a+x.n,0),wok=last7.reduce((a,x)=>a+x.ok,0),wmin=Math.round(last7.reduce((a,x)=>a+x.ms,0)/60000),active=last7.filter(x=>x.n).length;
 const adv=[];
 if(answered<20)adv.push(`Doe de <b>niveaucheck</b> (10 opdrachten). Daarna is het rapport veel betrouwbaarder.`);
 if(answered>=20&&mo>=6)adv.push(`${name} werkt duidelijk boven het niveau van groep ${u.groep}. Het spel heeft geen plafond, dus laat ${name} gewoon doorgroeien. Bespreek met de leerkracht of verrijking of compacten (minder herhaling van wat ${name} al kan) mogelijk is.`);
 WKEYS.forEach(k=>{const sk=u.skill[k];if(sk.n>=8&&LM.monthsAhead(LM.mastery(sk),u.groep,now)<=-4)adv.push(`Extra aandacht voor <b>${wname(k)}</b>. Speel vaker in deze wereld en kijk samen naar de uitleg na een fout.`);});
 const slow=Array.from({length:10},(_,i)=>i+1).filter(t=>['oefenen','bijna'].includes(LM.factState(u.facts['t'+t])));if(slow.length&&u.groep>=4)adv.push(`De tafel${slow.length>1?'s':''} van ${slow.join(', ')} ${slow.length>1?'gaan':'gaat'} nog niet vlot. Twee minuten per dag in de Rekensprint (keersommen) helpt het meest.`);
 if(['oefenen','bijna'].includes(LM.factState(u.facts.tot20))&&u.groep>=4)adv.push('Plus en min tot 20 gaat nog niet vlot. Dat is de basis voor al het rekenen daarna: oefen het kort in de Rekensprint (plussommen en minsommen).');
 if(weak.length)adv.push(`Lastig op dit moment: ${weak.map(x=>PZ.KIND_NAMES[x.k]).join(', ')}.`);
 if(answered>=20&&active<3)adv.push('Kort en vaak werkt het beste: 10 tot 15 minuten, 4 of 5 keer per week.');
 const HOME={add:'Thuis: trek twee speelkaarten en tel ze op, of vraag "hoeveel moet er nog bij tot 20 (of 100)?". Laat uitleggen hoe je kind het uitrekende.',tables:'Thuis: zeg de tafels kort hardop door elkaar, in de auto of op de fiets. Vijf minuten per dag werkt beter dan één keer lang.',fractions:'Thuis: verdeel pizza, taart of chocola eerlijk ("wie krijgt een kwart?"). Reken in de winkel samen de korting uit.',life:'Thuis: laat je kind afrekenen en het wisselgeld controleren. Vraag "hoe laat is het over een kwartier?" en laat de klok lezen.',logic:'Thuis: sudoku, Rush Hour of Set spelen, of samen een grafiek maken van het weer van deze week.'};
 const weakW=WKEYS.filter(k=>u.skill[k].n>=5).map(k=>[k,LM.mastery(u.skill[k])-exp]).sort((a,b)=>a[1]-b[1])[0];if(weakW&&answered>=15)adv.push(`<b>${wname(weakW[0])}</b> heeft de meeste groeiruimte. ${HOME[weakW[0]]}`);
 const errs=Object.entries(u.errs||{}).filter(([k,n])=>n>=2&&CO.BUG_INFO[k]).sort((a,b)=>b[1]-a[1]).slice(0,4);
 const checks=u.checks.slice(-3).reverse();
 return `<div class="report"><div class="page-heading rep-head"><div><div class="eyebrow">RAPPORT VOOR OUDERS · ${now.toLocaleDateString('nl-NL',{day:'numeric',month:'long',year:'numeric'})}</div><h1>${name} · groep ${u.groep}</h1><p>${answered?`Werkt gemiddeld op <b>${li.label.toLowerCase()}</b>. Verwacht in deze maand: ${LM.levelInfo(exp).label.toLowerCase()}. ${answered>=20?(mo>=3?`Dat is ongeveer <b>${mo} schoolmaanden voor</b>.`:mo<=-3?`Dat is ongeveer <b>${-mo} schoolmaanden achter</b>.`:'Dat is <b>op niveau</b>.'):'Na meer opdrachten wordt dit betrouwbaarder.'}`:`Nog geen opdrachten gemaakt. Start met de niveaucheck.`}</p></div><div class="rep-actions no-print"><button class="button purple" data-action="check-start">${icon('flag')} Niveaucheck</button><button class="button secondary" data-action="report-print">Print</button><button class="button secondary" data-action="players">Andere speler</button></div></div>
 <section class="rep-card"><h2>Werkniveau per wereld</h2><p class="rep-sub">De paarse stip is het niveau waarop ${name} ongeveer 3 van de 4 opdrachten goed maakt. De lichte balk laat zien hoe zeker dat is: met 80% kans ligt het echte niveau daarbinnen. Het streepje is wat je in deze maand van groep ${u.groep} mag verwachten.</p>${rows}</section>
 <section class="rep-card"><h2>Groei</h2>${growthChart(u)}</section>
 <div class="rep-grid"><section class="rep-card"><h2>Sterk in</h2>${kl(strong)}</section><section class="rep-card"><h2>Kan nog groeien</h2>${kl(weak)}</section></div>
 <section class="rep-card"><h2>Automatiseren</h2><p class="rep-sub">Vlot = minstens 9 van de 10 goed en meestal binnen 5 seconden. Dit meet het spel in de Tafelclub, de Rekensprint en bij keersommen.</p>${facts}</section>
 <div class="rep-grid"><section class="rep-card"><h2>Afgelopen 7 dagen</h2><div class="week"><div><b>${wn}</b><span>opdrachten</span></div><div><b>${wmin}</b><span>minuten</span></div><div><b>${wn?Math.round(wok/wn*100):0}%</b><span>direct goed</span></div><div><b>${active}</b><span>dagen geoefend</span></div></div></section>
 <section class="rep-card"><h2>Niveauchecks</h2>${checks.length?`<ul class="checks-list">${checks.map(c=>`<li><b>${new Date(c.date).toLocaleDateString('nl-NL',{day:'numeric',month:'short'})}</b> ${WKEYS.map(k=>`${wname(k)}: ${LM.levelInfo(c.levels[k]).label.toLowerCase()}`).join(' · ')}</li>`).join('')}</ul>`:'<p class="empty-note">Nog geen niveaucheck gedaan.</p>'}</section></div>
 <section class="rep-card"><h2>Fouten die vaker terugkomen</h2>${errs.length?`<p class="rep-sub">Het spel herkent bekende rekenfouten en geeft dan gerichte uitleg. Dit kwam het vaakst voor:</p><ul class="err-list">${errs.map(([k,n])=>`<li><b>${CO.BUG_INFO[k]}</b> <em>${n}×</em></li>`).join('')}</ul>`:'<p class="empty-note">Nog geen fouten die vaker terugkomen.</p>'}</section>
 <section class="rep-card advice"><h2>Tips</h2>${adv.length?`<ul>${adv.map(a=>`<li>${a}</li>`).join('')}</ul>`:'<p>Alles loopt goed. Blijf kort en regelmatig oefenen.</p>'}</section>
 <p class="rep-note"><b>Zo wordt gemeten.</b> Elke opdracht heeft een moeilijkheid. Het spel houdt per wereld een schatting bij plus hoe zeker die is. Een goed antwoord op een moeilijke opdracht telt zwaar, een slordige fout op een makkelijke opdracht nauwelijks. Half goed telt half mee, hulp telt iets minder, en bij rekenfeiten telt ook de snelheid. Hoe meer opdrachten, hoe smaller de balk. Na een pauze wordt de balk weer wat breder, want kinderen groeien ook buiten het spel.</p><p class="rep-note">Dit is een inschatting op basis van oefenen in RekenRijk, geen toets van school. Het niveau is gebaseerd op de leerlijn rekenen (SLO-tussendoelen, groep 3 t/m 8). Vergelijk het met de toetsen van school (bijvoorbeeld Cito of IEP) en bespreek grote verschillen met de leerkracht.</p></div>`;}
function tablePicker(){modal(`<div class="table-picker"><span class="eyebrow">DE TAFELCLUB</span><h2>Welke tafel kies jij?</h2><p>Oefen de tafel van 1 tot en met 10. Alle tijd voor jou.</p><div class="table-buttons">${Array.from({length:10},(_,i)=>`<button data-action="table-start" data-table="${i+1}" aria-label="Oefen de tafel van ${i+1}"><small>Tafel van</small><strong>${i+1}</strong></button>`).join('')}</div><button class="button purple" data-action="table-start" data-table="mix">${icon('sparkles')} Alle tafels door elkaar</button></div>`);speak('Welke tafel wil je oefenen? Tik op een getal van één tot en met tien. Of tik op de paarse knop voor alle tafels door elkaar.');}
function previewTrade(id){const pet=PETS[id],choices=tradeOptions(p(),id),count=ownedCount(p(),id);if(!pet||count<4||!choices.length)return;modal(`<div class="trade-preview">${petImg(id)}<span class="eyebrow">DE RUILWERKPLAATS</span><h2>4 × ${pet.name} → 1 nieuw</h2><p>Je krijgt een willekeurig ontbrekend beestje uit <strong>${GROUPS[pet.group].name}</strong>. Ook de secret kan verschijnen!</p><div class="trade-equation"><span>${count} nu</span>${icon('arrow')}<strong>${count-4} over</strong></div><p class="trade-consequence">${count===4?`${pet.name} gaat uit je actieve verzameling. Je krijgt er één ander beestje voor terug.`:`Je houdt ${count-4} exemplaren van ${pet.name}.`}</p><button class="button purple" data-action="trade-confirm" data-id="${id}">${icon('sparkles')} Ruil deze 4 exemplaren</button><button class="text-button" data-action="close">Nog even bewaren</button></div>`);speak(`Ruil vier ${pet.name} voor één ontbrekend vriendje uit ${GROUPS[pet.group].name}. Je houdt ${count-4} exemplaren over. Tik op de paarse knop als je wilt ruilen.`);}
function confirmTrade(id){if(page==='reward'||page==='play'||page==='battle')return;const result=tradeCopies(p(),id);if(!result.ok){toast(result.reason==='complete'?'Deze groep is al compleet.':'Je hebt nog geen vier exemplaren.');return;}pending={...result,score:0,revealed:false};page='reward';save();render();speak('Vier exemplaren geruild! Tik op het ei om je nieuwe vriendje te ontdekken.');}
